$_MODULE['<{pshubspot}prestashop>start_4f0d06ed7ddbbaefb28e4cb8fa3fefd3'] = 'Histórico de navegação e pedidos de clientes (visualizações de páginas, carrinhos gerados, histórico de pedidos, produtos adquiridos, entre outras opções) e Clientes, os pedidos em suas diferentes etapas são sincronizados em poucos minutos, você pode configurar o carrinho abandonado para o tempo que desejar a ser gerado.';
